class Solution {
public:
    int arrayNesting(vector<int>& nums) {
        int maxLen = 0, n = nums.size();
        for (int i = 0; i < n; ++i) {
            if (nums[i] >= 0) {
                int count = 0, curr = i;
                while (nums[curr] >= 0) {
                    int nxt = nums[curr];
                    nums[curr] = -1;
                    curr = nxt;
                    count++;
                }
                maxLen = max(maxLen, count);
            }
        }
        return maxLen;
    }
};

class Solution {
    public int arrayNesting(int[] nums) {
        int maxLen = 0, n = nums.length;
        for (int i = 0; i < n; i++) {
            if (nums[i] >= 0) {
                int count = 0, curr = i;
                while (nums[curr] >= 0) {
                    int nxt = nums[curr];
                    nums[curr] = -1;
                    curr = nxt;
                    count++;
                }
                maxLen = Math.max(maxLen, count);
            }
        }
        return maxLen;
    }
}

/**
