var arrayNesting = function(nums) {
    let maxLen = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        if (nums[i] >= 0) {
            let count = 0, curr = i;
            while (nums[curr] >= 0) {
                const nxt = nums[curr];
                nums[curr] = -1;
                curr = nxt;
                count++;
            }
            maxLen = Math.max(maxLen, count);
        }
    }
    return maxLen;
};
